#ifndef I2S_H__INCLUDED
#define I2S_H__INCLUDED

// i2s.h -- I2S microphone driver (GPIO bit-bang)
//
// INMP441 / SPH0645LM4H or compatible MEMS I2S mic
// Clocks generated by PWM (see pwm.h / pwm.c)
//
// Pin assignments (LoFive R1):
//   MIC_STAT  GPIO9   pin 15  SPI1.SS2  output  status/debug
//   MIC_LRCLK GPIO19  pin 23  PWM1.1    output  word select (WS)
//   MIC_BCLK  GPIO11  pin 17  PWM2.1    output  bit clock
//   MIC_DOUT  GPIO21  pin 25  PWM1.2    input   data from mic
//
// 2021-09-12  pds  initial cut for FE310
// 2026-11-17  pds/claude  split from fixfft.c

#include <stdint.h>

#define MIC_STAT  9   // LoFive pin 15, GPIO9/SPI1.SS2,  output from SoC
#define MIC_LRCLK 19  // LoFive pin 23, GPIO19/PWM1.1,  output from SoC
#define MIC_BCLK  11  // LoFive pin 17, GPIO11/PWM2.1,  output from SoC
#define MIC_DOUT  21  // LoFive pin 25, GPIO21/PWM1.2,  input  to   SoC
#define MIC_WS    MIC_LRCLK

void i2s_init     (void);
void i2s_read_sync(int n, int m, int16_t *left, int16_t *right);

#endif//I2S_H__INCLUDED
